package routehealth

import (
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

// DefaultCooldown is the process-local route-attempt TTL used when service
// configuration does not provide a health cooldown.
const DefaultCooldown = 30 * time.Second

// Attempt records availability feedback for one routed attempt.
type Attempt struct {
	Harness   string
	Provider  string
	Model     string
	Endpoint  string
	Status    string
	Reason    string
	Error     string
	Duration  time.Duration
	Timestamp time.Time
}

// Key is the normalized route-attempt identity.
type Key struct {
	Harness  string
	Provider string
	Model    string
	Endpoint string
}

// Record is an active route-attempt failure.
type Record struct {
	Key        Key
	Status     string
	Reason     string
	Error      string
	Duration   time.Duration
	RecordedAt time.Time
}

type metricRecord struct {
	attempts      int
	successes     int
	totalDuration time.Duration
	recordedAt    time.Time
}

// Store owns process-local route-attempt failure feedback and reliability
// metrics. It is safe for concurrent use.
type Store struct {
	mu       sync.RWMutex
	failures map[Key]Record
	metrics  map[Key]metricRecord
}

// NewStore returns an empty route-health store.
func NewStore() *Store {
	return &Store{
		failures: make(map[Key]Record),
		metrics:  make(map[Key]metricRecord),
	}
}

// RecordAttempt records availability feedback. Success clears matching active
// failures; non-success records an active failure and updates metrics.
func (s *Store) RecordAttempt(attempt Attempt) error {
	key := NormalizeKey(attempt)
	if key.Harness == "" && key.Provider == "" {
		return fmt.Errorf("route attempt requires harness or provider")
	}
	status := strings.ToLower(strings.TrimSpace(attempt.Status))
	if status == "" {
		return fmt.Errorf("route attempt status is required")
	}
	recordedAt := attempt.Timestamp
	if recordedAt.IsZero() {
		recordedAt = time.Now()
	}
	recordedAt = recordedAt.UTC()

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.failures == nil {
		s.failures = make(map[Key]Record)
	}
	if s.metrics == nil {
		s.metrics = make(map[Key]metricRecord)
	}
	s.recordMetricLocked(key, Succeeded(status), attempt.Duration, recordedAt)

	if Succeeded(status) {
		s.clearFailuresLocked(key)
		return nil
	}

	s.failures[key] = Record{
		Key:        key,
		Status:     status,
		Reason:     strings.TrimSpace(attempt.Reason),
		Error:      strings.TrimSpace(attempt.Error),
		Duration:   attempt.Duration,
		RecordedAt: recordedAt,
	}
	return nil
}

func (s *Store) recordMetricLocked(key Key, success bool, duration time.Duration, recordedAt time.Time) {
	record := s.metrics[key]
	record.attempts++
	if success {
		record.successes++
	}
	if duration > 0 {
		record.totalDuration += duration
	}
	record.recordedAt = recordedAt
	s.metrics[key] = record
}

// NormalizeKey returns the normalized route-attempt key for attempt.
func NormalizeKey(attempt Attempt) Key {
	return Key{
		Harness:  strings.TrimSpace(attempt.Harness),
		Provider: strings.TrimSpace(attempt.Provider),
		Model:    strings.TrimSpace(attempt.Model),
		Endpoint: strings.TrimSpace(attempt.Endpoint),
	}
}

// Succeeded reports whether status is a success spelling.
func Succeeded(status string) bool {
	switch status {
	case "success", "ok", "succeeded":
		return true
	default:
		return false
	}
}

func (s *Store) clearFailuresLocked(key Key) {
	for existing := range s.failures {
		if KeysMatch(existing, key) {
			delete(s.failures, existing)
		}
	}
}

// KeysMatch reports whether existing satisfies every non-empty query field.
func KeysMatch(existing, query Key) bool {
	if query.Harness != "" && existing.Harness != query.Harness {
		return false
	}
	if query.Provider != "" && existing.Provider != query.Provider {
		return false
	}
	if query.Model != "" && existing.Model != query.Model {
		return false
	}
	if query.Endpoint != "" && existing.Endpoint != query.Endpoint {
		return false
	}
	return true
}

// ActiveAttempts returns active failure records and removes expired records
// from the store.
func (s *Store) ActiveAttempts(now time.Time, ttl time.Duration) []Record {
	if s == nil {
		return nil
	}
	if ttl <= 0 {
		ttl = DefaultCooldown
	}
	if now.IsZero() {
		now = time.Now()
	}
	now = now.UTC()

	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.failures) == 0 {
		return nil
	}
	out := make([]Record, 0, len(s.failures))
	for key, record := range s.failures {
		if !record.RecordedAt.Add(ttl).After(now) {
			delete(s.failures, key)
			continue
		}
		out = append(out, record)
	}
	return out
}

// MetricSignals returns provider/model success-rate and latency maps suitable
// for routing inputs.
func (s *Store) MetricSignals(now time.Time, ttl time.Duration) (map[string]float64, map[string]float64) {
	if s == nil {
		return nil, nil
	}
	if ttl <= 0 {
		ttl = DefaultCooldown
	}
	if now.IsZero() {
		now = time.Now()
	}
	now = now.UTC()

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.metrics) == 0 {
		return nil, nil
	}
	successRate := make(map[string]float64, len(s.metrics))

package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Request is the routing input. All fields are optional except at least
// one of {Profile, ModelRef, Model, Harness, Provider} should be set
// (otherwise the engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Profile            string // "cheap" | "standard" | "smart"
	ModelRef           string // catalog alias (e.g. "qwen/qwen3.6")
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "agent" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name               string
	BaseURL            string
	EndpointName       string
	EndpointBaseURL    string
	DefaultModel       string
	CostClass          string
	DiscoveredIDs      []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted bool
	ContextWindows     map[string]int
	SupportsTools      bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness    string
	Provider   string
	Endpoint   string
	Model      string
	Reason     string
	Candidates []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Endpoint           string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS   float64
	SuccessRate float64
	CostClass   string
	SpeedTPS    float64

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)

package routing

import (
	"fmt"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Capabilities describes what a (harness, provider, model) tuple can do.
// Populated from harness config + catalog metadata + provider discovery.
type Capabilities struct {
	ContextWindow      int      // resolved tokens; 0 = unknown
	SupportsTools      bool     // supports tool/function calling
	SupportsStreaming  bool     // supports streaming responses
	SupportedReasoning []string // supported public reasoning values
	MaxReasoningTokens int      // 0 means numeric reasoning is unsupported/unknown
	SupportedPerms     []string // {"safe","supervised","unrestricted"} subset
	ExactPinSupport    bool     // accepts exact concrete model pins
	SupportedModels    []string // nil = no static allow-list
}

// HasReasoning returns true if the candidate supports the requested reasoning
// value. Empty, auto, off, and numeric 0 impose no requirement.
func (c Capabilities) HasReasoning(value string) bool {
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return false
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return true
	case reasoning.KindTokens:
		return c.MaxReasoningTokens > 0 && policy.Tokens <= c.MaxReasoningTokens
	case reasoning.KindNamed:
		for _, supported := range c.SupportedReasoning {
			normalized, err := reasoning.Normalize(supported)
			if err == nil && normalized == policy.Value {
				return true
			}
		}
		return false
	default:
		return false
	}
}

// HasPermissions returns true if the candidate supports the requested level.
// An empty permission level always returns true.
func (c Capabilities) HasPermissions(perm string) bool {
	if perm == "" {
		return true
	}
	for _, p := range c.SupportedPerms {
		if strings.EqualFold(p, perm) {
			return true
		}
	}
	return false
}

// HasModel returns true when the exact model pin is within the static
// harness allow-list. A nil allow-list means the harness delegates validation
// to provider-side model checks.
func (c Capabilities) HasModel(model string) bool {
	if c.SupportedModels == nil || model == "" {
		return true
	}
	for _, supported := range c.SupportedModels {
		if supported == model {
			return true
		}
	}
	return false
}

// CheckGating applies all capability gates against a request and returns
// the first failure reason (free-form string for diagnostics) plus the
// typed FilterReason category for the failure. Returns ("", FilterReasonEligible)
// when all gates pass.
//
// The typed return is the authoritative classification — callers must not
// re-classify by parsing the string. The string is for human-readable
// diagnostics only.
//
// Fixes ddx-4817edfd subtree: pre-dispatch capability check covering
// context window, tool support, effort, permissions.
func CheckGating(cap Capabilities, req Request) (string, FilterReason) {
	// Context window gating: if the request declares prompt size or an effort
	// that implies a minimum context, reject candidates that can't fit.
	minCtx := req.MinContextWindow()
	if minCtx > 0 && cap.ContextWindow > 0 && cap.ContextWindow < minCtx {
		return fmt.Sprintf("context window %d < required %d", cap.ContextWindow, minCtx), FilterReasonContextTooSmall
	}

	// Tool-calling support gating.
	if req.RequiresTools && !cap.SupportsTools {
		return "tool calling not supported", FilterReasonNoToolSupport
	}

	if !cap.HasReasoning(req.Reasoning) {
		return fmt.Sprintf("reasoning %q not supported", req.Reasoning), FilterReasonReasoningUnsupported
	}

	// Permissions support gating.
	if !cap.HasPermissions(req.Permissions) {
		return fmt.Sprintf("permissions %q not supported", req.Permissions), FilterReasonScoredBelowTop
	}

	if req.Model != "" && !cap.HasModel(req.Model) {
		return "model not in harness allow-list", FilterReasonScoredBelowTop
	}

	// Exact-pin gating: an explicit Model field requires ExactPinSupport.
	if req.Model != "" && req.ModelRef == "" && !cap.ExactPinSupport {
		return "exact model pin not supported", FilterReasonScoredBelowTop
	}

	return "", FilterReasonEligible
}

// CheckPowerEligibility applies catalog-power gates for unpinned automatic
// routing. Exact model pins bypass this gate so callers can intentionally run
// a discovered model that is missing catalog power or marked exact-pin-only.
func CheckPowerEligibility(lookup func(string) (ModelEligibility, bool), model string, req Request) (string, FilterReason) {
	if req.Model != "" || lookup == nil {
		return "", FilterReasonEligible
	}
	if model == "" {
		return "model has no catalog power metadata", FilterReasonPowerMissing
	}
	eligibility, ok := lookup(model)
	if !ok {
		if req.MinPower > 0 || req.MaxPower > 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return "", FilterReasonEligible
	}
	if eligibility.ExactPinOnly {
		return fmt.Sprintf("model %q is exact-pin-only", model), FilterReasonExactPinOnly
	}
	if !eligibility.AutoRoutable {
		if eligibility.Power <= 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return fmt.Sprintf("model %q is not auto-routable", model), FilterReasonNotAutoRoutable
	}
	if req.MinPower > 0 && eligibility.Power < req.MinPower {
		return fmt.Sprintf("model %q power %d < min_power %d", model, eligibility.Power, req.MinPower), FilterReasonBelowMinPower
	}
	if req.MaxPower > 0 && eligibility.Power > req.MaxPower {
		return fmt.Sprintf("model %q power %d > max_power %d", model, eligibility.Power, req.MaxPower), FilterReasonAboveMaxPower
	}
	return "", FilterReasonEligible
}

// resolveRequestReasoning returns a copy of req with Reasoning resolved to the
// catalog's surface_policy reasoning_default for the request's profile/surface
// when the request asks for Reasoning=auto. This must run before CheckGating
// so candidates that only support a different reasoning level (e.g. an
// off-only variant under a profile whose surface default is "high") are
// correctly disqualified by the capability gate. Other Reasoning values
// (unset, off, named, numeric) are left untouched, preserving the existing
// behavior of those code paths.
func resolveRequestReasoning(req Request, surface string, resolver func(profile, surface string) (string, bool)) Request {
	if resolver == nil || req.Profile == "" {
		return req
	}
	policy, err := reasoning.ParseString(req.Reasoning)
	if err != nil || policy.Kind != reasoning.KindAuto {
		return req
	}
	resolved, ok := resolver(req.Profile, surface)
	if !ok || resolved == "" {
		return req
	}
	out := req
	out.Reasoning = resolved
	return out
}

package routing

import (
	"errors"
	"fmt"
	"slices"
	"strings"
	"testing"
	"time"
)

// newTestRoutingEngine returns a baseline Inputs with two harnesses and a
// trivial catalog resolver. Mirrors the DDx newTestRunnerForRouting helper.
func newTestRoutingEngine() Inputs {
	return Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "agent",
				Surface:             "embedded-openai",
				CostClass:           "local",
				IsLocal:             true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:          "vidar-omlx",
						BaseURL:       "http://vidar:11434",
						DiscoveredIDs: []string{"Qwen3.6-35B-A3B-4bit", "MiniMax-M2.5-MLX-4bit"},
						SupportsTools: true,
						ContextWindows: map[string]int{
							"Qwen3.6-35B-A3B-4bit": 256000,
						},
					},
					{
						Name:          "openrouter",
						BaseURL:       "https://openrouter.ai/api/v1",
						DiscoveredIDs: []string{"qwen/qwen3.6", "anthropic/claude-sonnet-4-6"},
						SupportsTools: true,
					},
				},
			},
			{
				Name:                "codex",
				Surface:             "codex",
				CostClass:           "medium",
				IsSubscription:      true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				DefaultModel:        "gpt-5.4",
			},
			{
				Name:                "claude",
				Surface:             "claude",
				CostClass:           "medium",
				IsSubscription:      true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				DefaultModel:        "claude-sonnet-4-6",
			},
		},
		CatalogResolver: func(ref, surface string) (string, bool) {
			// Trivial test catalog.
			switch ref {
			case "cheap":
				if surface == "embedded-openai" {
					return "qwen/qwen3.6", true
				}
				if surface == "codex" {
					return "gpt-5.4-mini", true
				}
				if surface == "claude" {
					return "claude-haiku-4-6", true
				}
			case "smart":
				if surface == "claude" {
					return "claude-opus-4-7", true
				}
				if surface == "codex" {
					return "gpt-5.4", true
				}
			case "qwen/qwen3.6":
				if surface == "embedded-openai" {
					return "qwen/qwen3.6", true
				}
			}
			return "", false
		},
		Now: time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC),
	}
}

// === Smell 1: ddx-8610020e — Provider field present from day one ===
//
// RouteRequest carries Provider as a hard pin; the engine must never select
// a different provider when Provider is set.
func TestSmellProviderFieldDayOne(t *testing.T) {
	in := newTestRoutingEngine()

	// Provider pin: req.Provider constrains routing.
	req := Request{Profile: "cheap", Provider: "vidar-omlx"}
	dec, err := Resolve(req, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Provider != "vidar-omlx" {
		t.Errorf("provider=vidar-omlx soft pref: got %q, want vidar-omlx", dec.Provider)
	}

	// Hard pin: Harness=agent + Provider=openrouter constrains routing.
	hardReq := Request{Harness: "agent", Provider: "openrouter", Model: "qwen/qwen3.6"}
	dec2, err := Resolve(hardReq, in)
	if err != nil {
		t.Fatalf("hard pin Resolve: %v", err)
	}
	if dec2.Provider != "openrouter" {
		t.Errorf("hard pin: got provider=%q, want openrouter", dec2.Provider)
	}
}

func TestExplicitProviderPinDoesNotSubstituteAvailableProvider(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "agent",
				Surface:             "embedded-openai",
				CostClass:           "local",
				IsLocal:             true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:               "lmstudio",
						DiscoveryAttempted: true,
						SupportsTools:      true,
					},
					{
						Name:          "openrouter",
						DiscoveredIDs: []string{"qwen/qwen3.6"},
						SupportsTools: true,
					},
				},
			},
		},
		Now: time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC),
	}

	dec, err := Resolve(Request{Provider: "lmstudio", Model: "qwen/qwen3.6"}, in)
	if err == nil {
		t.Fatalf("Resolve selected provider=%q model=%q, want no viable candidate", dec.Provider, dec.Model)
	}
	var noViable *NoViableCandidateError
	if !errors.As(err, &noViable) {
		t.Fatalf("error type=%T, want *NoViableCandidateError: %v", err, err)
	}
	if !strings.Contains(err.Error(), "provider=lmstudio") {
		t.Fatalf("error=%q, want provider pin detail", err.Error())
	}
	if dec == nil || dec.Harness != "" || dec.Provider != "" || dec.Model != "" {
		t.Fatalf("error decision selected a candidate: %#v", dec)
	}

	seenOpenRouter := false
	for _, c := range dec.Candidates {
		if c.Provider == "openrouter" {
			seenOpenRouter = true
			if c.Eligible {
				t.Fatalf("openrouter must not remain eligible under provider pin: %#v", c)
			}
			if c.FilterReason != FilterReasonPinMismatch {
				t.Fatalf("openrouter filter reason=%q, want %q", c.FilterReason, FilterReasonPinMismatch)
			}
			if !strings.Contains(c.Reason, "provider override requires lmstudio") {
				t.Fatalf("openrouter rejection reason=%q, want provider pin detail", c.Reason)
			}
		}
		if c.Eligible && c.Provider != "lmstudio" {
			t.Fatalf("non-pinned provider remained eligible: %#v", c)
		}
	}
	if !seenOpenRouter {
		t.Fatal("test must include the attractive non-pinned openrouter candidate")
	}
}

