package serviceimpl

import "time"

// Clock is the API-neutral time seam used by service implementation state.
// It deliberately has no dependency on root package contract types so the
// root facade can import this package without creating a cycle.
type Clock func() time.Time

// SystemClock returns the current UTC wall-clock time.
func SystemClock() time.Time {
	return time.Now().UTC()
}

// RuntimeDeps groups constructor dependencies that are safe to pass from the
// root facade into internal implementation packages.
type RuntimeDeps struct {
	Now Clock
}

// Runtime is implementation-local service state that can be constructed from
// the root facade without depending on root public contract types.
type Runtime struct {
	deps RuntimeDeps
}

// NewRuntime constructs implementation state with defaulted dependencies.
func NewRuntime(deps RuntimeDeps) Runtime {
	return Runtime{deps: RuntimeDeps{Now: deps.Clock()}}
}

// Clock returns the configured clock or the system clock when no test seam is
// supplied.
func (d RuntimeDeps) Clock() Clock {
	if d.Now != nil {
		return d.Now
	}
	return SystemClock
}

// Now returns the runtime clock value normalized to UTC.
func (r Runtime) Now() time.Time {
	return r.deps.Clock()().UTC()
}

package fizeau

import (
	"fmt"
	"strings"
)

// Reserved cross-tool metadata keys (CONTRACT-003 § ExecuteRequest.Metadata).
// When the caller also sets one of these top-level fields and the same key
// in Metadata, the top-level field wins and a MetadataKeyCollision warning
// is emitted on the final event.
const (
	MetadataKeyRole          = "role"
	MetadataKeyCorrelationID = "correlation_id"
)

// MetadataWarningCodeKeyCollision is the ServiceFinalWarning.Code stamped
// onto the final event when caller-supplied Metadata duplicates a reserved
// top-level field (Role or CorrelationID).
const MetadataWarningCodeKeyCollision = "metadata_key_collision"

// Role normalization bounds (CONTRACT-003).
const roleMaxLen = 64

// CorrelationID normalization bounds (CONTRACT-003).
const correlationIDMaxLen = 256

// RoleNormalizationError is returned pre-dispatch when ServiceExecuteRequest.Role
// or RouteRequest.Role fails normalization (lowercased, alphanumeric+hyphen
// only, max 64 chars).
type RoleNormalizationError struct {
	// Role is the value that failed normalization.
	Role string
	// Reason is a short human-readable reason (e.g. "too long",
	// "contains invalid character").
	Reason string
}

func (e *RoleNormalizationError) Error() string {
	return fmt.Sprintf("invalid Role %q: %s", e.Role, e.Reason)
}

// CorrelationIDNormalizationError is returned pre-dispatch when
// ServiceExecuteRequest.CorrelationID or RouteRequest.CorrelationID fails
// normalization (printable ASCII, no whitespace except hyphen/colon/underscore,
// max 256 chars).
type CorrelationIDNormalizationError struct {
	CorrelationID string
	Reason        string
}

func (e *CorrelationIDNormalizationError) Error() string {
	return fmt.Sprintf("invalid CorrelationID %q: %s", e.CorrelationID, e.Reason)
}

// ValidateRole returns nil when role is empty (unset) or already
// normalized, and a typed *RoleNormalizationError otherwise. The empty
// string is treated as "unset". Callers should use the value as-is when
// validation succeeds — normalization here is identity-or-reject (we do
// not silently rewrite caller input).
func ValidateRole(role string) error {
	if role == "" {
		return nil
	}
	if len(role) > roleMaxLen {
		return &RoleNormalizationError{
			Role:   role,
			Reason: fmt.Sprintf("length %d exceeds max %d", len(role), roleMaxLen),
		}
	}
	for i := 0; i < len(role); i++ {
		c := role[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= '0' && c <= '9':
		case c == '-':
		default:
			return &RoleNormalizationError{
				Role:   role,
				Reason: fmt.Sprintf("character %q at offset %d is not lowercase alphanumeric or hyphen", string(c), i),
			}
		}
	}
	return nil
}

// ValidateCorrelationID returns nil when id is empty or normalized, and a
// typed *CorrelationIDNormalizationError otherwise.
func ValidateCorrelationID(id string) error {
	if id == "" {
		return nil
	}
	if len(id) > correlationIDMaxLen {
		return &CorrelationIDNormalizationError{
			CorrelationID: id,
			Reason:        fmt.Sprintf("length %d exceeds max %d", len(id), correlationIDMaxLen),
		}
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		switch {
		case c >= 0x21 && c <= 0x7E && c != ' ':
			// printable ASCII; whitespace already excluded by 0x21 lower bound.
			// allow hyphen/colon/underscore implicitly along with the rest of
			// the printable range. Only reject if outside the printable range.
		default:
			return &CorrelationIDNormalizationError{
				CorrelationID: id,
				Reason:        fmt.Sprintf("byte 0x%02x at offset %d is not printable ASCII (no control chars or whitespace)", c, i),
			}
		}
	}
	return nil
}

// metaWithRoleAndCorrelation overlays the caller-supplied top-level Role
// and CorrelationID onto a copy of meta under the reserved metadata keys,
// per CONTRACT-003. Top-level wins on collision; existing meta entries
// for unrelated keys are preserved. Returns meta unchanged when both
// fields are empty (avoids unnecessary allocation).
func metaWithRoleAndCorrelation(meta map[string]string, role, correlationID string) map[string]string {
	if role == "" && correlationID == "" {
		return meta
	}
	out := make(map[string]string, len(meta)+2)
	for k, v := range meta {
		out[k] = v
	}
	if role != "" {
		out[MetadataKeyRole] = role
	}
	if correlationID != "" {
		out[MetadataKeyCorrelationID] = correlationID
	}
	return out
}

// metadataReservedKeyCollisions returns the reserved metadata keys whose
// caller-supplied Metadata value would be overridden by a non-empty
// top-level Role or CorrelationID. Used to emit the MetadataKeyCollision
// warning on the final event.
func metadataReservedKeyCollisions(meta map[string]string, role, correlationID string) []string {
	var out []string
	if role != "" {
		if v, ok := meta[MetadataKeyRole]; ok && v != "" && v != role {
			out = append(out, MetadataKeyRole)
		}
	}
	if correlationID != "" {
		if v, ok := meta[MetadataKeyCorrelationID]; ok && v != "" && v != correlationID {
			out = append(out, MetadataKeyCorrelationID)
		}
	}
	return out
}

// metadataKeyCollisionMessage formats a human-readable message for the
// MetadataKeyCollision warning surfaced on the final event.
func metadataKeyCollisionMessage(keys []string) string {
	if len(keys) == 0 {
		return ""
	}
	return fmt.Sprintf("top-level field(s) %s overrode caller Metadata entries with the same reserved key", strings.Join(keys, ", "))
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// agent-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	if profile == "" {
		profile = reqProfileFromModelRef(cat, req.ModelRef)
	}
	modelRef := reqModelRefStripProfile(cat, req.ModelRef)
	providerPreference, err := providerPreferenceForProfile(cat, profile)
	if err != nil {
		return &RouteDecision{}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	rReq := routing.Request{
		Profile:               profile,
		ModelRef:              modelRef,
		Model:                 req.Model,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		MinPower:              req.MinPower,
		MaxPower:              req.MaxPower,
	}
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		return result, publicRoutingError(err, result.Candidates)
	}
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:    dec.Harness,
		Provider:   dec.Provider,
		Endpoint:   dec.Endpoint,
		Model:      dec.Model,
		Reason:     dec.Reason,
		Candidates: routeCandidatesFromInternal(dec.Candidates),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Endpoint:           candidate.Endpoint,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		Components: RouteCandidateComponents{
			Power:            candidate.Power,
			Cost:             candidate.CostUSDPer1kTokens,
			CostClass:        candidate.CostClass,
			LatencyMS:        candidate.LatencyMS,
			SpeedTPS:         candidate.SpeedTPS,
			SuccessRate:      candidate.SuccessRate,
			QuotaOK:          candidate.QuotaOK,
			QuotaPercentUsed: candidate.QuotaPercentUsed,
			QuotaTrend:       candidate.QuotaTrend,
			Capability:       capabilityScoreForCostClass(candidate.CostClass),
		},
	}
}

// publicFilterReason maps the typed FilterReason emitted by the internal
// routing engine to the public FilterReason* string constant. The internal
// constants are defined to share string values with the public surface, so
// this is a one-line passthrough — there is no string parsing.
func publicFilterReason(c routing.Candidate) string {
	if c.Eligible {
		return ""
	}
	return string(c.FilterReason)
}

// capabilityScoreForCostClass maps the harness cost class to a coarse
// numeric capability proxy. Mirrors the engine's costClassRank ordering
// (more expensive ≈ more capable) for reporting purposes only.
func capabilityScoreForCostClass(class string) float64 {
	switch class {
	case "local":
		return 0
	case "cheap":
		return 1
	case "medium", "":
		return 2
	case "expensive":
		return 3
	case "experimental":
		return -1
	default:
		return 0
	}
}

// escalateProfileLadder walks routing.ProfileEscalationLadder when Resolve
// returns a "no eligible candidate" error and the request's profile is in
// the ladder. Returns (true, decision, nil) when a higher tier resolves to
// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
// the entire remaining ladder is also empty. Returns (false, _, _) when
// escalation does not apply (hard pin error, profile not in ladder, etc.).
func escalateProfileLadder(req routing.Request, in routing.Inputs, origErr error) (bool, *routing.Decision, error) {
	if origErr == nil || req.Profile == "" {
		return false, nil, nil
	}
	if !shouldEscalateOnError(origErr) {
		return false, nil, nil
	}
	startIdx := -1
	for i, p := range routing.ProfileEscalationLadder {
		if p == req.Profile {
			startIdx = i
			break
		}
	}
	if startIdx < 0 {
		return false, nil, nil
	}
	for i := startIdx + 1; i < len(routing.ProfileEscalationLadder); i++ {
		probe := req
		probe.Profile = routing.ProfileEscalationLadder[i]
		dec, err := routing.Resolve(probe, in)
		if err == nil && dec != nil && dec.Harness != "" {
			return true, dec, nil
		}
	}
	return true, nil, &routing.ErrNoLiveProvider{
		PromptTokens:  req.EstimatedPromptTokens,
		RequiresTools: req.RequiresTools,
		StartingTier:  req.Profile,
	}
}

// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
// ErrProfilePinConflict) are surfaced as-is — escalating past an explicit
// pin would silently change the caller's intent.
func shouldEscalateOnError(err error) bool {
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return false
	}
	var pinErr *routing.ErrProfilePinConflict
	if errors.As(err, &pinErr) {
		return false
	}
	return true
}

	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)
	}
	return fmt.Sprintf("no viable routing candidate: %d candidates rejected", e.Rejected)
}

// ErrNoLiveProvider reports that profile-tier escalation walked the entire
// ladder (cheap → standard → smart) without finding a live provider that
// can serve the request. Callers translate this into a precise user-facing
// message naming the prompt size and tool requirement so operators know
// what capability is missing across all tiers.
type ErrNoLiveProvider struct {
	// PromptTokens is the request's EstimatedPromptTokens at the time
	// escalation began. Zero means no prompt-token gating was active.
	PromptTokens int
	// RequiresTools mirrors the request's RequiresTools flag.
	RequiresTools bool
	// StartingTier is the profile name that escalation began from
	// (the profile in the original request).
	StartingTier string
}

func (e *ErrNoLiveProvider) Error() string {
	return fmt.Sprintf("no live provider supports prompt of %d tokens with tools=%v at tier ≥ %s",
		e.PromptTokens, e.RequiresTools, e.StartingTier)
}

// ProfileEscalationLadder is the fixed cheap → standard → smart progression
// service.ResolveRoute walks when every candidate at the requested tier is
// filtered out (unhealthy or capability-rejected).
var ProfileEscalationLadder = []string{"cheap", "standard", "smart"}

// Inputs bundles the engine's external data sources.
type Inputs struct {
	Harnesses           []HarnessEntry
	HistoricalSuccess   map[string]float64   // by harness name; -1 = insufficient data
	ObservedSpeedTPS    map[string]float64   // by "provider:model"
	ProviderSuccessRate map[string]float64   // by ProviderModelKey(provider, endpoint, model)
	ObservedLatencyMS   map[string]float64   // by ProviderModelKey(provider, endpoint, model)
	ProviderCooldowns   map[string]time.Time // by provider name
	CooldownDuration    time.Duration        // 0 = no cooldown enforcement

	// ProviderQuotaExhaustedUntil maps provider name → retry_after time.
	// A provider with retry_after > Now is treated as quota_exhausted and
	// disqualified from candidate selection. The service maintains the
	// per-provider quota state machine and projects it into this map for
	// each routing call.
	ProviderQuotaExhaustedUntil map[string]time.Time
	Now                         time.Time // injected for deterministic testing; default time.Now()
	CatalogResolver             func(ref, surface string) (concreteModel string, ok bool)
	CatalogCandidatesResolver   func(ref, surface string) (concreteModels []string, ok bool)
	ModelEligibility            func(model string) (ModelEligibility, bool)

	// ReasoningResolver returns the catalog's surface_policy reasoning_default
	// for a (profile, surface) pair. When set, buildHarnessCandidates uses it
	// to resolve Reasoning=auto to a concrete level before invoking the
	// capability gate, so candidates that cannot satisfy the resolved level
	// (e.g. an off-only variant under a profile whose surface default is
	// "high") are correctly disqualified instead of slipping through.
	ReasoningResolver func(profile, surface string) (resolved string, ok bool)
}

// ModelEligibility is the routing engine's catalog-power view for one model.
// Unknown or zero-power models are still usable through exact Model pins, but
// are excluded from unpinned automatic routing.
type ModelEligibility struct {
	Power        int
	ExactPinOnly bool
	AutoRoutable bool
}

// candidateInternal carries the engine's intermediate state per (harness, provider, model).
type candidateInternal struct {
	Harness               string
	Provider              string
	EndpointName          string
	Model                 string
	CostClass             string
	CostUSDPer1kTokens    float64
	CostSource            string
	Power                 int
	IsSubscription        bool
	QuotaOK               bool
	QuotaPercentUsed      int
	QuotaStale            bool
	QuotaTrend            string
	SubscriptionOK        bool
	HistoricalSuccessRate float64
	ProviderSuccessRate   float64
	ObservedTokensPerSec  float64
	ObservedLatencyMS     float64
	InCooldown            bool
	ProviderAffinityMatch bool
	ProviderPreference    string
}

// ProviderModelKey is the metrics key used by routing callers for provider
// performance signals. Endpoint is optional; when empty the key remains
// compatible with older provider:model metrics.
func ProviderModelKey(provider, endpoint, model string) string {
	if endpoint == "" {
		return provider + ":" + model
	}
	return provider + "@" + endpoint + ":" + model
}

// Resolve runs the engine end-to-end and returns a Decision.
//
// The engine:
//  1. Enumerates (harness, provider, model) candidates from inputs.
//  2. Applies gating (capability, override, model-pin, surface).
//  3. Scores per profile policy with cooldown demotion + perf bias.
//  4. Sorts viable → score → cost → locality → name.
//  5. Returns the top viable candidate with the full ranked list.
//
// Returns an error only when no viable candidate exists.
func Resolve(req Request, in Inputs) (*Decision, error) {
	if in.Now.IsZero() {
		in.Now = time.Now()
	}

	canonicalHarness := req.Harness
	if canonicalHarness == "local" {
		canonicalHarness = "agent"
	}

	var ranked []rankedCandidate
	for _, h := range in.Harnesses {
		// TestOnly harnesses (script/virtual) only reachable via explicit override.
		if h.TestOnly && canonicalHarness != h.Name {
			continue
		}
		// Automatic profile/tier routing is restricted to harnesses with full
		// coverage. Explicit Harness pins can still use experimental/ad-hoc
		// harnesses.
		if canonicalHarness == "" && !h.AutoRoutingEligible {
			continue
		}
		// Hard harness override: skip non-matching harnesses.
		if canonicalHarness != "" && canonicalHarness != h.Name {
			continue
		}
		entries := buildHarnessCandidates(h, req, in)
		ranked = append(ranked, entries...)
	}

	// Compute scores.
	for i := range ranked {
		ranked[i].out.Score = scorePolicy(req.Profile, ranked[i].internal)
		if ranked[i].out.Eligible {
			ranked[i].out.Reason = fmt.Sprintf("profile=%s; score=%.1f", req.Profile, ranked[i].out.Score)
		}
	}
	neutralCost, hasKnownCost := neutralKnownCost(ranked)

	// Sort: eligible first, then descending score, then cost, then locality,
	// then alphabetical.
	sort.SliceStable(ranked, func(i, j int) bool {
		ei, ej := ranked[i].out.Eligible, ranked[j].out.Eligible
		if ei != ej {
			return ei
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			EndpointName:          p.EndpointName,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
		}
		out = append(out, rankedCandidate{
			out: Candidate{
				Harness:            h.Name,
				Provider:           p.Name,
				Endpoint:           p.EndpointName,
				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

func candidateProviderIdentity(h HarnessEntry, p ProviderEntry) string {
	if p.Name != "" {
		return p.Name
	}
	return h.Name
}

func candidateCostClass(h HarnessEntry, p ProviderEntry) string {
	if p.CostClass != "" {
		return p.CostClass
	}
	return h.CostClass
}

func normalizeCostSource(source string) string {
	switch source {
	case CostSourceCatalog, CostSourceSubscription, CostSourceUserConfig:
		return source
	default:
		return CostSourceUnknown
	}
}

func neutralKnownCost(candidates []rankedCandidate) (float64, bool) {
	var total float64
	var count int
	for _, candidate := range candidates {
		if !candidate.out.Eligible {
			continue
		}
		if normalizeCostSource(candidate.out.CostSource) == CostSourceUnknown {
			continue
		}
		total += candidate.out.CostUSDPer1kTokens
		count++
	}
	if count == 0 {
		return 0, false
	}
	return total / float64(count), true
}

func candidateCostTieValue(candidate rankedCandidate, neutralCost float64) float64 {
	if normalizeCostSource(candidate.out.CostSource) == CostSourceUnknown {
		return neutralCost
	}
	return candidate.out.CostUSDPer1kTokens
}

// resolveModel picks the concrete model string for a (harness, provider) pair
// given the request. Returns the model and a non-empty rejection reason if
// resolution fails.
func resolveModel(h HarnessEntry, p ProviderEntry, req Request, in Inputs) (string, string) {
	// 1. Exact pin.
	if req.Model != "" {
		// If the provider has discovery data, try fuzzy matching to map the
		// canonical/short ref to the provider-native ID.
		if len(p.DiscoveredIDs) > 0 {
			if matched := FuzzyMatch(req.Model, p.DiscoveredIDs); matched != "" {
				return matched, ""
			}
			return "", fmt.Sprintf("model %q not on provider %q", req.Model, p.Name)
		}
		if p.DiscoveryAttempted {
			return "", fmt.Sprintf("provider %q has no live discovered models", p.Name)
		}
		return req.Model, ""
	}

	// 2. Catalog ref.
	if req.ModelRef != "" {
		if len(p.DiscoveredIDs) > 0 && in.CatalogCandidatesResolver != nil {
			if candidates, ok := in.CatalogCandidatesResolver(req.ModelRef, h.Surface); ok {
				for _, candidate := range candidates {
					if matched := FuzzyMatch(candidate, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
				}
				return "", fmt.Sprintf("model ref %q not on provider %q", req.ModelRef, p.Name)
			}
		}
		if in.CatalogResolver != nil {
			if concrete, ok := in.CatalogResolver(req.ModelRef, h.Surface); ok {
				// If discovery is available, double-check the concrete ID
				// (or the original ref) appears on this provider.
				if len(p.DiscoveredIDs) > 0 {
					if matched := FuzzyMatch(concrete, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					// Try the original ref against discovery.
					if matched := FuzzyMatch(req.ModelRef, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					return "", fmt.Sprintf("model ref %q not on provider %q", req.ModelRef, p.Name)
				}
				return concrete, ""
			}
			return "", fmt.Sprintf("model ref %q not available on surface %q", req.ModelRef, h.Surface)
		}
		if p.DiscoveryAttempted {
			return "", fmt.Sprintf("provider %q has no live discovered models", p.Name)
		}
		// No catalog: pass the ref through.
		return req.ModelRef, ""
	}

	// 3. Profile.
	if req.Profile != "" {
		if len(p.DiscoveredIDs) > 0 && in.CatalogCandidatesResolver != nil {
			if candidates, ok := in.CatalogCandidatesResolver(req.Profile, h.Surface); ok {
				for _, candidate := range candidates {
					if matched := FuzzyMatch(candidate, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
				}
				return "", fmt.Sprintf("profile %q has no candidate served by provider %q", req.Profile, p.Name)
			}
		}
		if in.CatalogResolver != nil {
			if concrete, ok := in.CatalogResolver(req.Profile, h.Surface); ok {
				// If discovery is available, verify the resolved model exists.
				if len(p.DiscoveredIDs) > 0 {
					if matched := FuzzyMatch(concrete, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					// Also try the original profile ref (handles bare-leaf refs
					// against discovery). Fixes ddx-2f5a2284.
					if matched := FuzzyMatch(req.Profile, p.DiscoveredIDs); matched != "" {
						return matched, ""
					}
					return "", fmt.Sprintf("profile %q resolves to %q but provider %q does not serve it", req.Profile, concrete, p.Name)
				}
				return concrete, ""
			}
			// No catalog mapping for this surface — fall through to defaults
			// only if defaults exist; otherwise reject so escalation skips
			// this candidate (fixes ddx-3c5ba7cc).
			if p.DefaultModel == "" && h.DefaultModel == "" {
				return "", fmt.Sprintf("profile %q not available on surface %q", req.Profile, h.Surface)
			}
		} else if p.DefaultModel == "" && h.DefaultModel == "" {
			return "", fmt.Sprintf("profile %q not available on surface %q", req.Profile, h.Surface)
		}
		// No catalog hit; fall through to default.
	}

	// 4. Provider default → harness default. Empty default is acceptable
	// when no request fields constrained model selection — orphan validation
	// happens at dispatch time.
	if p.DefaultModel != "" {
		if len(p.DiscoveredIDs) > 0 {
			if matched := FuzzyMatch(p.DefaultModel, p.DiscoveredIDs); matched != "" {
				return matched, ""
			}
			return "", fmt.Sprintf("provider default %q not on provider %q", p.DefaultModel, p.Name)
		}
		return p.DefaultModel, ""
	}
	if h.DefaultModel != "" {
		return h.DefaultModel, ""
	}
	return "", ""
}

