 10	// DefaultLeaseTTL bounds how long an in-process sticky route lease may live
 11	// without being refreshed.
 12	const DefaultLeaseTTL = 5 * time.Minute
 13	
 14	// LeaseKey identifies one sticky lease scope.
 15	type LeaseKey struct {
 16		StickyKey string
 17		Provider  string
 18		Model     string
 19	}
 20	
 21	// Lease describes one sticky endpoint assignment.
 22	type Lease struct {
 23		Key         LeaseKey
 24		Provider    string
 25		Endpoint    string
 26		Model       string
 27		AcquiredAt  time.Time
 28		RefreshedAt time.Time
 29		ExpiresAt   time.Time
 30	}
 31	
 32	// LeaseInvalidation records why a lease was removed.
 33	type LeaseInvalidation struct {
 34		Key        LeaseKey
 35		Provider   string
 36		Endpoint   string
 37		Model      string
 38		Reason     string
 39		RecordedAt time.Time
 40	}
 41	
 42	// LeaseStore owns in-process sticky route assignments. It is safe for
 43	// concurrent use.
 44	type LeaseStore struct {
 45		mu            sync.Mutex
 46		leases        map[LeaseKey]Lease
 47		invalidations map[LeaseKey]LeaseInvalidation
 48	}
 49	
 50	// NewLeaseStore returns an empty lease store.
 51	func NewLeaseStore() *LeaseStore {
 52		return &LeaseStore{
 53			leases:        make(map[LeaseKey]Lease),
 54			invalidations: make(map[LeaseKey]LeaseInvalidation),
 55		}
 56	}
 57	
 58	// NormalizeLeaseKey trims whitespace from the lease dimensions.
 59	func NormalizeLeaseKey(stickyKey, provider, model string) LeaseKey {
 60		return LeaseKey{
 61			StickyKey: strings.TrimSpace(stickyKey),
 62			Provider:  strings.TrimSpace(provider),
 63			Model:     strings.TrimSpace(model),
 64		}
 65	}
 66	
 67	// Live returns the current lease for key when it has not expired.
 68	func (s *LeaseStore) Live(now time.Time, key LeaseKey) (Lease, bool) {
 69		if s == nil {
 70			return Lease{}, false
 71		}
 72		now = normalizeLeaseNow(now)
 73	
 74		s.mu.Lock()
 75		defer s.mu.Unlock()
 76		s.expireLocked(now)
 77		lease, ok := s.leases[key]
 78		if !ok {
 79			return Lease{}, false
 80		}
 81		return lease, true
 82	}
 83	
 84	// Acquire stores or refreshes a lease for key.
 85	func (s *LeaseStore) Acquire(now time.Time, ttl time.Duration, key LeaseKey, provider, endpoint, model string) Lease {
 86		if s == nil {
 87			return Lease{}
 88		}
 89		now = normalizeLeaseNow(now)
 90		if ttl <= 0 {
 91			ttl = DefaultLeaseTTL
 92		}
 93		key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)
 94		provider = strings.TrimSpace(provider)
 95		endpoint = strings.TrimSpace(endpoint)
 96		model = strings.TrimSpace(model)
 97	
 98		s.mu.Lock()
 99		defer s.mu.Unlock()
100		s.expireLocked(now)
101	
102		lease := Lease{
103			Key:         key,
104			Provider:    provider,
105			Endpoint:    endpoint,
106			Model:       model,
107			AcquiredAt:  now,
108			RefreshedAt: now,
109			ExpiresAt:   now.Add(ttl),
110		}
111		if existing, ok := s.leases[key]; ok {
112			if existing.Provider == provider && existing.Endpoint == endpoint && existing.Model == model {
113				lease.AcquiredAt = existing.AcquiredAt
114			}
115		}
116		s.leases[key] = lease
117		delete(s.invalidations, key)
118		return lease
119	}
120	
121	// Invalidate removes the lease for key and records the reason.
122	func (s *LeaseStore) Invalidate(now time.Time, key LeaseKey, reason string) (LeaseInvalidation, bool) {
123		if s == nil {
124			return LeaseInvalidation{}, false
125		}
126		now = normalizeLeaseNow(now)
127		key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)
128	
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		s.expireLocked(now)
132		lease, ok := s.leases[key]
133		if !ok {
134			return LeaseInvalidation{}, false
135		}
136		delete(s.leases, key)
137		invalidation := LeaseInvalidation{
138			Key:        key,
139			Provider:   lease.Provider,
140			Endpoint:   lease.Endpoint,
141			Model:      lease.Model,
142			Reason:     strings.TrimSpace(reason),
143			RecordedAt: now,
144		}
145		s.invalidations[key] = invalidation
146		return invalidation, true
147	}
