149	// InvalidateEndpoint removes every lease for the provider/model scope that
150	// points at the named endpoint and records the supplied reason.
151	func (s *LeaseStore) InvalidateEndpoint(now time.Time, provider, endpoint, model, reason string) []LeaseInvalidation {
152		if s == nil {
153			return nil
154		}
155		now = normalizeLeaseNow(now)
156		provider = strings.TrimSpace(provider)
157		endpoint = strings.TrimSpace(endpoint)
158		model = strings.TrimSpace(model)
159	
160		s.mu.Lock()
161		defer s.mu.Unlock()
162		s.expireLocked(now)
163		if len(s.leases) == 0 {
164			return nil
165		}
166		var out []LeaseInvalidation
167		for key, lease := range s.leases {
168			if provider != "" && lease.Provider != provider {
169				continue
170			}
171			if endpoint != "" && lease.Endpoint != endpoint {
172				continue
173			}
174			if model != "" && lease.Model != model {
175				continue
176			}
177			delete(s.leases, key)
178			invalidation := LeaseInvalidation{
179				Key:        key,
180				Provider:   lease.Provider,
181				Endpoint:   lease.Endpoint,
182				Model:      lease.Model,
183				Reason:     strings.TrimSpace(reason),
184				RecordedAt: now,
185			}
186			s.invalidations[key] = invalidation
187			out = append(out, invalidation)
188		}
189		return out
190	}
