 19	func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
 20		if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
 21			return
 22		}
 23		if decision.Harness != "agent" || decision.Provider == "" {
 24			return
 25		}
 26	
 27		now := time.Now().UTC()
 28		store := s.routeLeaseStore()
 29		baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
 30		if baseProvider == "" {
 31			baseProvider = decision.Provider
 32		}
 33		if baseProvider == "" || decision.Model == "" {
 34			return
 35		}
 36	
 37		key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
 38		if lease, ok := store.Live(now, key); ok {
 39			if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
 40				store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
 41				decision.Provider = candidate.Provider
 42				decision.Endpoint = candidate.Endpoint
 43				return
 44			}
 45			reason := "endpoint disappeared"
 46			if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
 47				reason = candidate.Reason
 48				if reason == "" {
 49					reason = "sticky endpoint became ineligible"
 50				}
 51			} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
 52				reason = candidate.Reason
 53				if reason == "" {
 54					reason = "sticky endpoint became ineligible"
 55				}
 56			}
 57			store.Invalidate(now, key, reason)
 58		}
 59	
 60		candidate, found := stickyLeasePick(decision.Candidates, decision.Harness, baseProvider, decision.Model, store.LeaseCounts(now, baseProvider, decision.Model))
 61		if !found || !candidate.Eligible {
 62			return
 63		}
 64		chosenEndpoint := candidate.Endpoint
 65		if chosenEndpoint == "" {
 66			_, chosenEndpoint, _ = splitEndpointProviderRef(candidate.Provider)
 67		}
 68		if chosenEndpoint == "" {
 69			chosenEndpoint = candidate.Provider
 70		}
 71		store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
 72		decision.Provider = candidate.Provider
 73		decision.Endpoint = candidate.Endpoint
 74	}
