 76	func stickyLeasePick(candidates []RouteCandidate, harness, provider, model string, counts map[string]int) (RouteCandidate, bool) {
 77		var chosen RouteCandidate
 78		found := false
 79		for _, candidate := range candidates {
 80			if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
 81				continue
 82			}
 83			baseProvider, _, _ := splitEndpointProviderRef(candidate.Provider)
 84			if baseProvider == "" {
 85				baseProvider = candidate.Provider
 86			}
 87			if baseProvider != provider {
 88				continue
 89			}
 90			if candidate.Endpoint == "" && candidate.Provider == "" {
 91				continue
 92			}
 93			if !found {
 94				chosen = candidate
 95				found = true
 96				continue
 97			}
 98			leftCount := counts[endpointOf(candidate)]
 99			rightCount := counts[endpointOf(chosen)]
100			if leftCount != rightCount {
101				if leftCount < rightCount {
102					chosen = candidate
103				}
104				continue
105			}
106			if candidate.Score != chosen.Score {
107				if candidate.Score > chosen.Score {
108					chosen = candidate
109				}
110				continue
111			}
112			if endpointOf(candidate) < endpointOf(chosen) {
113				chosen = candidate
114			}
115		}
116		return chosen, found
117	}
118	
119	func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
120		for _, candidate := range candidates {
121			if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
122				continue
123			}
124			baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
125			if baseProvider == "" {
126				baseProvider = candidate.Provider
127			}
128			if baseProvider != provider {
129				continue
130			}
131			if candidateEndpoint == "" {
132				candidateEndpoint = candidate.Endpoint
133			}
134			if candidateEndpoint == endpoint {
135				return candidate, true
136			}
137		}
138		return RouteCandidate{}, false
139	}
140	
141	func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
142		for _, candidate := range candidates {
143			if candidate.Harness != harness {
144				continue
145			}
146			baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
147			if baseProvider == "" {
148				baseProvider = candidate.Provider
149			}
150			if baseProvider != provider {
151				continue
152			}
153			if candidateEndpoint == "" {
154				candidateEndpoint = candidate.Endpoint
155			}
156			if candidateEndpoint == endpoint {
157				return candidate, true
158			}
159		}
160		return RouteCandidate{}, false
161	}
162	
163	func endpointOf(candidate RouteCandidate) string {
164		if _, endpoint, ok := splitEndpointProviderRef(candidate.Provider); ok && endpoint != "" {
165			return endpoint
166		}
167		return candidate.Endpoint
168	}

