 28			return nil, err
 29		}
 30		if err := ValidateCorrelationID(req.CorrelationID); err != nil {
 31			return nil, err
 32		}
 33		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
 34		cat := serviceRoutingCatalog()
 35		profile := req.Profile
 36		if profile == "" {
 37			profile = reqProfileFromModelRef(cat, req.ModelRef)
 38		}
 39		modelRef := reqModelRefStripProfile(cat, req.ModelRef)
 40		providerPreference, err := providerPreferenceForProfile(cat, profile)
 41		if err != nil {
 42			return &RouteDecision{}, err
 43		}
 44		in := s.buildRoutingInputsWithCatalog(ctx, cat)
 45	
 46		rReq := routing.Request{
 47			Profile:               profile,
 48			ModelRef:              modelRef,
 49			Model:                 req.Model,
 50			Provider:              req.Provider,
 51			Harness:               req.Harness,
 52			Reasoning:             effectiveReasoningString(req.Reasoning),
 53			Permissions:           req.Permissions,
 54			ProviderPreference:    providerPreference,
 55			EstimatedPromptTokens: req.EstimatedPromptTokens,
 56			RequiresTools:         req.RequiresTools,
 57			MinPower:              req.MinPower,
 58			MaxPower:              req.MaxPower,
 59		}
 60		s.applyRouteAttemptCooldowns(&in)
 61		dec, err := routing.Resolve(rReq, in)
 62		if err != nil {
 63			if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
 64				dec = edec
 65				err = eerr
 66			}
 67		}
