56		}
57		if live, ok := store.Live(now.Add(5*time.Second), key); ok || live != (Lease{}) {
58			t.Fatalf("invalidated lease still live: %#v ok=%v", live, ok)
59		}
60		if got := store.InvalidateEndpoint(now.Add(6*time.Second), "agent", "desk-b", "model-a", "model unavailable"); len(got) != 0 {
61			t.Fatalf("InvalidateEndpoint should not match removed lease, got %#v", got)
62		}
63		if inv2, ok := store.LastInvalidation(key); !ok || inv2.Reason != "endpoint disappeared" {
64			t.Fatalf("last invalidation=%#v ok=%v, want endpoint disappeared", inv2, ok)
65		}
66	}
